 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    # Extract the colored motifs as 4-connected objects.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            todo = [(r, c)]
            seen.add((r, c))
            points = []
            while todo:
                x, y = todo.pop()
                points.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        todo.append((nx, ny))
            r0 = min(x for x, y in points)
            c0 = min(y for x, y in points)
            shape = {(x-r0, y-c0) for x, y in points}
            objects.append({'color': color, 'shape': shape, 'r': r0, 'c': c0})

    # Repeated identical motifs of a color represent the same tile; retain the
    # first (uppermost/leftmost) instance, as in the examples.
    unique = []
    signatures = set()
    for obj in objects:
        sig = (obj['color'], frozenset(obj['shape']))
        if sig not in signatures:
            signatures.add(sig)
            unique.append(obj)
    objects = unique

    def is_hollow(obj):
        shape = obj['shape']
        bh = max(r for r, c in shape) + 1
        bw = max(c for r, c in shape) + 1
        empty = {(r, c) for r in range(bh) for c in range(bw) if (r, c) not in shape}
        # An enclosed 4-connected empty region indicates a frame/ring motif.
        while empty:
            start = next(iter(empty))
            region = {start}
            todo = [start]
            empty.remove(start)
            touches_edge = False
            while todo:
                r, c = todo.pop()
                if r == 0 or c == 0 or r == bh-1 or c == bw-1:
                    touches_edge = True
                for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if (nr, nc) in empty:
                        empty.remove((nr, nc))
                        region.add((nr, nc))
                        todo.append((nr, nc))
            if not touches_edge:
                return True
        return False

    for obj in objects:
        obj['up'] = is_hollow(obj)

    def occupied(except_obj):
        cells = set()
        for obj in objects:
            if obj is except_obj:
                continue
            for dr, dc in obj['shape']:
                cells.add((obj['r'] + dr, obj['c'] + dc))
        return cells

    # Hollow motifs rise; solid motifs fall. Iterate until no motif can move,
    # allowing an object to continue once another moving object clears its way.
    for _ in range(h + 1):
        changed = False
        for direction in ("up", "down"):
            group = [o for o in objects if o['up'] == (direction == 'up')]
            group.sort(key=lambda o: (o['r'], o['c']), reverse=(direction == 'down'))
            step = -1 if direction == 'up' else 1
            for obj in group:
                nr = obj['r'] + step
                if any(nr + dr < 0 or nr + dr >= h for dr, dc in obj['shape']):
                    continue
                occ = occupied(obj)
                if any((nr + dr, obj['c'] + dc) in occ for dr, dc in obj['shape']):
                    continue
                obj['r'] = nr
                changed = True
        if not changed:
            break

    out = [[0] * w for _ in range(h)]
    for obj in objects:
        for dr, dc in obj['shape']:
            rr, cc = obj['r'] + dr, obj['c'] + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = obj['color']
    return out
